[InitializeOnLoad]public static class VerifyMorningEntry{
const string TestKey="MorningEntryAcceptance";static IEnumerator steps;static double next;static int count;static string error;static Keyboard keyboard;
static ProgressionState State=>(ProgressionState)typeof(GameManager).GetProperty("State",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(GameManager.Instance);
static object Field(object o,string n)=>o.GetType().GetField(n,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(o);
static void Check(bool ok,string reason){count++;if(!ok)throw new Exception(reason);}
static VerifyMorningEntry(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(!SessionState.GetBool(TestKey,false))return;if(s==PlayModeStateChange.EnteredPlayMode){steps=Steps();next=EditorApplication.timeSinceStartup+3;count=0;error=null;}if(s==PlayModeStateChange.ExitingPlayMode)Restore();};Application.logMessageReceived+=(m,t,l)=>{if(steps!=null&&(l==LogType.Error||l==LogType.Exception)&&!t.Contains("UnityEditor.Search.SearchDatabase"))error=m;};}
[MenuItem("Prototype/Test new morning and entry audio")]
public static void Run(){if(EditorApplication.isPlaying)return;if(SessionState.GetBool(TestKey,false))Restore();foreach(var suffix in new[]{"",".bak",".tmp"}){var p=ProgressionSave.PathName+suffix;SessionState.SetString(TestKey+suffix,File.Exists(p)?Convert.ToBase64String(File.ReadAllBytes(p)):"");}SessionState.SetInt(TestKey+"Focus",(int)InputSystem.settings.backgroundBehavior);SessionState.SetInt(TestKey+"Lang",PlayerPrefs.GetInt("Story.Language",0));PlayerPrefs.SetInt("Story.Language",0);SessionState.SetBool(TestKey+"Bg",Application.runInBackground);Application.runInBackground=true;SessionState.SetBool(TestKey,true);SessionState.SetBool(DayOneSupernovaEvent.SuppressionKey,true);ProgressionSave.Write(new ProgressionState());EditorSceneManager.OpenScene("Assets/Scenes/Apartment/Bedroom.unity");EditorApplication.isPlaying=true;}
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(steps==null){if(!EditorApplication.isPlaying&&File.Exists("../morning-entry-request.txt")){File.Delete("../morning-entry-request.txt");Run();}return;}if(EditorApplication.timeSinceStartup<next)return;try{if(error!=null)throw new Exception(error);if(steps.MoveNext())next=EditorApplication.timeSinceStartup+(float)steps.Current;else Finish(null);}catch(Exception e){Finish(e.ToString());}}
static void Press(UnityEngine.InputSystem.Key key){keyboard.MakeCurrent();InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));}static void Release()=>InputSystem.QueueStateEvent(keyboard,new KeyboardState());
static void Place(Vector2 p){var g=GameObject.FindWithTag("Player");g.transform.position=p;g.GetComponent<Rigidbody2D>().position=p;Physics2D.SyncTransforms();}
static IEnumerator Steps(){InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;if(StoryText.English)StoryText.ToggleLanguage();while(GameManager.Instance==null)yield return .2f;var audio=ApartmentAudio.Instance;
Check(audio.Ready&&Resources.Load<AudioClip>("Audio/TitleOrbit")!=null&&Resources.Load<AudioClip>("Audio/OpeningScream")!=null,"Independent title and scream assets");
MainMenuUI.ReturnToMainMenu();yield return 5f;var title=(AudioSource)Field(audio,"title");var home=(AudioSource)Field(audio,"home");var hidden=(AudioSource)Field(audio,"hidden");
Check(title.isPlaying&&title.volume>home.volume&&audio.MenuBlend>.95f,"Title owns its music");Check(Math.Abs(title.timeSamples-home.timeSamples)<1024&&Math.Abs(home.timeSamples-hidden.timeSamples)<1024,"Three loop stems share DSP phase");int before=home.timeSamples;
if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../menu-seven-day.png");yield return .4f;}MainMenuUI.Instance.StartGame();MainMenuUI.Instance.StartGame();yield return 6.5f;Check(audio.ScreamPlaying,"Crescendo vocal effect actually plays");Check(MainMenuUI.IsOpening,"Opening blocks duplicate start");
using(var sky=new OpeningSky()){var t=sky.Render(6,.65f);File.WriteAllBytes("../entry-eyes-fire.png",t.EncodeToPNG());Check(t.width==480&&t.filterMode==FilterMode.Point,"Eyes and flames stay pixelated");bool opaque=true;foreach(var px in t.GetPixels32())if(px.a!=255)opaque=false;Check(opaque,"Opening cannot leak the room through shaded eye pixels");Check(t.GetPixel(460,140).maxColorComponent<.003f,"Eyes emerge from black rather than gray fog");}
if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../entry-eyes-runtime.png");yield return .4f;var screen=new Texture2D(2,2);screen.LoadImage(File.ReadAllBytes("../entry-eyes-runtime.png"));Check(screen.GetPixel((int)(screen.width*460f/480),(int)(screen.height*140f/270)).maxColorComponent<.025f,"Composited opening remains black without apartment ambience");UnityEngine.Object.DestroyImmediate(screen);}yield return 4f;float beforeHandoff=title.volume;yield return 1.2f;Check(Mathf.Abs(title.volume-beforeHandoff)<.08f,"Title gain stays smooth at dream handoff");
Check(!MainMenuUI.IsOpening&&MainMenuUI.IsVisible==false,"Opening hands off to dream");Check(audio.MenuBlend>0&&audio.MenuBlend<1&&title.volume>0&&home.volume>0,"Music overlaps during gradual handoff");int delta=(home.timeSamples-before+home.clip.samples)%home.clip.samples;Check(delta>9*home.clip.frequency&&delta<14*home.clip.frequency,"Journey reset preserves music clock");
Check(State.journal.Count==0&&!State.dreamSeen,"Dream is not recorded as evidence");keyboard=InputSystem.AddDevice<Keyboard>("MorningEntryKeyboard");keyboard.MakeCurrent();
Press(UnityEngine.InputSystem.Key.E);yield return .3f;Release();Check((int)Field(UnityEngine.Object.FindAnyObjectByType<StoryJournal>(),"dreamPage")==0,"Dream ignores old E binding");
if(!Application.isBatchMode)ScreenCapture.CaptureScreenshot("../dream-enter-only.png");
for(int i=0;i<4;i++){Press(UnityEngine.InputSystem.Key.Enter);yield return .3f;Release();yield return .2f;}
Check(State.dreamSeen&&MorningRoutine.Instance.IsWaking&&SceneManager.GetActiveScene().name=="Bedroom","Enter completes dream and starts bedside waking");Check(State.journal.Count==0,"Waking creates no automatic notebook entry");
if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../wake-placeholder.png");yield return .4f;}yield return 4f;var routine=MorningRoutine.Instance;var player=GameObject.FindWithTag("Player");Check(!routine.IsWaking&&Vector2.Distance(player.transform.position,routine.Bedside)<.15f,"Player finishes standing beside bed");Check(player.GetComponent<Rigidbody2D>().simulated&&CultNeighbor.Instance.ImpactCount>0,"Wake restores body and plays hammer impacts");Check(State.morningStage==2&&routine.Objective==StoryText.Current.morning.neighbor,"Neighbor objective");
var window=UnityEngine.Object.FindAnyObjectByType<WindowLookout2D>();var beforeWindow=player.transform.position;Place((Vector2)window.transform.position+Vector2.down*1.2f);yield return .2f;Check(!window.CanInteract&&!window.TryOpen(),"Window ignores distant player");Place((Vector2)window.transform.position+Vector2.down*.25f);yield return .2f;Check(window.CanInteract&&window.TryOpen(),"Window remains reachable close to glass");window.CloseView();Place(beforeWindow);if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../bedside-wake.png");yield return .4f;}TimeManager.Instance.AdvanceTime();yield return .4f;Check(!DayOneSupernovaEvent.Instance.IsPresenting&&SceneManager.GetActiveScene().name=="Bedroom","Time progression no longer forces a bulletin or teleport");TimeManager.Instance.ResetToDayOne();
SceneManager.LoadScene("LivingRoom");yield return .7f;var earlyFridge=GameObject.Find("Refrigerator").GetComponent<SpriteRenderer>().bounds;Place(new Vector2(earlyFridge.center.x,earlyFridge.min.y-.35f));yield return .3f;Check(!routine.CanOpenFridge&&!routine.OpenFridge(),"Fridge cannot bypass neighbor introduction");SceneManager.LoadScene("Corridor");yield return 5f;Check(CultNeighbor.WorldBlocked&&Field(CultNeighbor.Instance,"view").ToString()=="DayOne","Neighbor initiates warning without a question");if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../neighbor-first-warning.png");yield return .4f;}Check(CultNeighbor.Instance.TalkDayOne(),"Day one dialogue remains available");for(int i=0;i<StoryText.Current.cult.dayOne.Length;i++)CultNeighbor.Instance.Advance();Check(State.morningStage==3&&routine.Objective==StoryText.Current.morning.food,"Conversation guides player home for food");
SceneManager.LoadScene("LivingRoom");yield return .7f;Check(routine.Objective==StoryText.Current.morning.kitchen,"Living room guides toward kitchen area");var fridge=GameObject.Find("Refrigerator");var bounds=fridge.GetComponent<SpriteRenderer>().bounds;Place(new Vector2(bounds.center.x,bounds.min.y-.35f));yield return .3f;
Check(routine.CanOpenFridge&&routine.OpenFridge(),"Fridge is interactable");yield return 1.4f;Check(State.fridgeOpened&&DayOneSupernovaEvent.Instance.IsPresenting,"Opening fridge starts normal television news");
var news=StoryText.Current.dayOneBroadcast;Check(news.pages.Length==4&&news.pages[0].Contains("威尔")&&news.pages[1].Contains("101")&&news.pages[2].Contains("三角教")&&news.pages[3].Contains("超新星"),"Four requested ordinary headlines");Check(!string.Join("",news.pages).Contains("SKT-079"),"Old emergency draft removed");Check(State.journal.Count==0,"News does not automatically collect evidence");
if(!Application.isBatchMode){ScreenCapture.CaptureScreenshot("../fridge-normal-news.png");yield return .4f;}for(int i=0;i<4;i++)DayOneSupernovaEvent.Instance.Advance();yield return .4f;Check(!DayOneSupernovaEvent.Instance.IsPresenting&&State.dayOneSupernovaSeen&&State.morningStage==5,"News finishes morning flow");Check(TimeManager.Instance.Days==1&&TimeManager.Instance.Period==TimePeriod.Morning,"Short fridge interaction preserves time period");
Check(Investigation.Collect("skt079-broadcast")&&Investigation.Evidence("skt079-broadcast").body.Contains("101"),"News extract remains optional active collection");Check(!DayOneSupernovaEvent.Instance.PlayFromFridge(),"Fridge news does not auto repeat");
var save=ProgressionSave.Load();Check(save.fridgeOpened&&save.morningStage==5&&save.cultDayOneTalked,"Morning and route state persists");State.morningStage=2;TimeManager.Instance.SleepUntilNextMorning();yield return .4f;Check(State.morningStage==3&&routine.CanOpenFridge,"Missing the day-one neighbor does not lock the fridge on later days");Check(error==null,"No runtime errors");}
static void Finish(string failure){steps=null;File.WriteAllText("../morning-entry-validation.txt",failure==null?"PASS: "+count+" checks; independent synchronized title score; rising scream playback; uninterrupted music handoff; Enter-only dream; no auto dream record; bedside wake and hammer; neighbor / home / kitchen guidance; fridge-triggered normal four-headline news; optional collection; no forced time event; persistence.":"FAIL: "+failure);EditorApplication.isPlaying=false;Restore();if(Application.isBatchMode)EditorApplication.Exit(failure==null?0:1);}
static void Restore(){if(!SessionState.GetBool(TestKey,false))return;SessionState.SetBool(TestKey,false);InputSystem.settings.backgroundBehavior=(InputSettings.BackgroundBehavior)SessionState.GetInt(TestKey+"Focus",0);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);keyboard=null;foreach(var suffix in new[]{"",".bak",".tmp"}){var p=ProgressionSave.PathName+suffix;var b=SessionState.GetString(TestKey+suffix,"");if(b.Length>0)File.WriteAllBytes(p,Convert.FromBase64String(b));else if(File.Exists(p))File.Delete(p);}PlayerPrefs.SetInt("Story.Language",SessionState.GetInt(TestKey+"Lang",0));PlayerPrefs.Save();Application.runInBackground=SessionState.GetBool(TestKey+"Bg",false);SessionState.SetBool(DayOneSupernovaEvent.SuppressionKey,false);steps=null;}
}
